-- Migration: Year 2 - Sexual & Forensic Pathology MCQs Part 1 (1-38)
-- Date: 2026-04-24

BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Sexual & Forensic Pathology', 'sexual-forensic-pathology', 3, 2, 62)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES

    -- PROSTATE: BPH (1-12)
    (v_topic_id, 'Benign Prostatic Hyperplasia (BPH) most commonly arises in which zone of the prostate?', '["Peripheral zone", "Transitional (periurethral) zone", "Central zone", "Fibromuscular stroma"]', 1, 'BPH arises in the transitional (periurethral) zone, compressing the urethra from within and causing obstructive urinary symptoms (decreased stream, hesitancy, nocturia, incomplete emptying). In contrast, prostate cancer most commonly arises in the peripheral zone.'),
    (v_topic_id, 'BPH is driven by dihydrotestosterone (DHT). Which enzyme converts testosterone to DHT in prostate stromal cells?', '["Aromatase", "5-alpha reductase type 2", "17-beta hydroxysteroid dehydrogenase", "3-beta hydroxysteroid dehydrogenase"]', 1, 'DHT is formed by 5-alpha reductase (type 2 in prostate stroma). DHT binds androgen receptors with 10x greater affinity than testosterone and is the main driver of prostatic growth. 5-alpha reductase inhibitors (finasteride, dutasteride) reduce prostate volume by ~25% over 6 months.'),
    (v_topic_id, 'What is the histological hallmark of BPH?', '["Atypical glands with nuclear pleomorphism", "Nodular proliferation of both glandular epithelium AND fibromuscular stroma in the periurethral transition zone, creating nodules that compress the urethra", "Diffuse prostatic fibrosis", "Infiltrative glands permeating fat"]', 1, 'BPH is a HYPERPLASIA (increase in cell number), not hypertrophy. Both stromal and glandular elements proliferate, forming nodules. The nodules compress the urethral lumen. The peripheral zone is compressed outward, forming a pseudocapsule around the BPH nodules.'),
    (v_topic_id, 'Which urinary symptom is most characteristic of BPH?', '["Gross painless hematuria", "Lower urinary tract obstructive symptoms: weak stream, hesitancy, terminal dribbling, incomplete emptying, and nocturia", "Acute flank pain radiating to groin (renal colic)", "Continuous urinary incontinence"]', 1, 'BPH compresses the prostatic urethra. LUTS (lower urinary tract symptoms): obstructive (weak stream, hesitancy, straining) and storage (urgency, frequency, nocturia). Complications: acute urinary retention, recurrent UTIs, hydronephrosis, bladder stones from stasis, and bladder hypertrophy (trabeculation, diverticula).'),
    (v_topic_id, 'Alpha-1 adrenergic blockers (tamsulosin, doxazosin) are used in BPH. What is their mechanism?', '["They reduce prostate volume by blocking DHT receptors", "They relax smooth muscle in the prostate stroma and bladder neck (alpha-1 receptors), immediately reducing urethral resistance and improving urine flow", "They inhibit 5-alpha reductase", "They block androgen receptors on glandular epithelium"]', 1, 'Alpha-1 blockers relax prostatic and bladder neck smooth muscle within days (unlike 5-alpha reductase inhibitors which take 6 months). They do NOT reduce prostate volume. Side effect: orthostatic hypotension, retrograde ejaculation (especially tamsulosin — alpha-1A selective).'),
    (v_topic_id, 'Finasteride (5-alpha reductase inhibitor) lowers PSA levels. What is the clinical implication for prostate cancer screening?', '["Finasteride makes PSA unreliable for all patients", "Finasteride reduces PSA by ~50% after 6 months; a PSA that does not fall by 50% or that rises on finasteride should be investigated for prostate cancer", "Finasteride raises PSA by inhibiting DHT", "PSA is unaffected by finasteride"]', 1, 'Finasteride reduces PSA by approximately 50% in patients with BPH. If a patient on finasteride has PSA that fails to decline by 50% (or any rise), it suggests prostate cancer. Multiply the measured PSA by 2 to estimate the true PSA for cancer risk assessment in men on finasteride.'),
    (v_topic_id, 'Acute urinary retention is a complication of BPH. What is the emergency management?', '["Immediate TURP (transurethral resection)", "Urethral catheterization to decompress the bladder, followed by alpha-blocker initiation", "IV furosemide to reduce urine production", "Suprapubic percussion"]', 1, 'Acute urinary retention = inability to void despite full bladder (painful, palpable bladder). Emergency: Foley catheter placement. After decompression, start alpha-blocker (tamsulosin) and consider 5-ARI. Post-void residual >300 mL warrants evaluation. TURP is elective, not emergent.'),
    (v_topic_id, 'Bladder trabeculation seen on cystoscopy in a BPH patient is caused by?', '["Bladder cancer infiltrating the muscle", "Detrusor muscle hypertrophy from chronically straining against urethral obstruction, creating ridges (trabeculations) and pockets (diverticula)", "Chronic cystitis fibrosis", "Amyloid deposition in bladder wall"]', 1, 'Detrusor muscle compensates for urethral obstruction by hypertrophying. Over time, muscle bundles become irregular, creating ridges (trabeculations) on the inner bladder surface. Between these ridges, mucosa herniates outward forming diverticula (no muscle in diverticular wall → stasis → infection/stones → rarely carcinoma).'),
    (v_topic_id, 'BPH is NOT a premalignant condition and does NOT increase risk of prostate cancer. However, both BPH and prostate cancer can elevate PSA. What accounts for PSA elevation in BPH?', '["BPH glands produce an abnormal glycoprotein form of PSA", "Enlarged prostate has more total glandular tissue producing PSA; BPH disrupts the normal glandular architecture, allowing more PSA to leak into the bloodstream", "BPH causes inflammation that stimulates PSA gene expression", "PSA is produced by stromal cells, which dominate BPH"]', 1, 'PSA (prostate-specific antigen) is produced by prostatic epithelial cells (not cancer-specific). Total prostate volume is the main driver of PSA in BPH. PSA density (PSA divided by prostate volume) and free/total PSA ratio help distinguish BPH from cancer. In BPH, free PSA is relatively higher (lower %free PSA suggests cancer).'),
    (v_topic_id, 'Which surgical procedure is the gold standard treatment for symptomatic BPH refractory to medications?', '["Open radical prostatectomy", "Transurethral Resection of the Prostate (TURP)", "Radical cystectomy", "Bilateral orchiectomy"]', 1, 'TURP (cystoscopic resection of periurethral prostatic tissue) is the gold standard surgical treatment for BPH. Complications: retrograde ejaculation (most common, ~75%), TURP syndrome (dilutional hyponatremia from absorption of hypotonic irrigating fluid), bleeding, urethral stricture, and incontinence (<1%).'),
    (v_topic_id, 'TURP syndrome is a serious complication of TURP. What is the pathophysiology?', '["Urethral perforation causing intraperitoneal bleeding", "Absorption of large volumes of hypotonic glycine or sorbitol irrigating fluid into the bloodstream causes dilutional hyponatremia and hypervolemia → cerebral edema, confusion, seizures, pulmonary edema", "Retrograde ejaculation causing infertility", "Sepsis from irrigation fluid contamination"]', 1, 'TURP syndrome: absorption of hypotonic irrigating solution through open prostatic venous sinuses during TURP → dilutional hyponatremia (Na+ drops rapidly) → cerebral edema (confusion, seizures, visual disturbance). Also: hypervolemia → pulmonary edema. Treatment: hypertonic saline (if severe), furosemide, supportive care.'),
    (v_topic_id, 'Prostatitis can be classified into four categories. Acute bacterial prostatitis presents with?', '["Asymptomatic elevated PSA only", "Sudden onset of fever, chills, perineal/lower back pain, dysuria, and an exquisitely tender, boggy prostate on DRE — most commonly caused by E. coli", "Chronic perineal discomfort without systemic symptoms", "Obstructive voiding symptoms identical to BPH"]', 1, 'Acute bacterial prostatitis: E. coli (most common), Klebsiella, Proteus. Systemic features (fever, rigors) + irritative and obstructive LUTS + exquisitely tender prostate on DRE. CAUTION: vigorous prostate massage is contraindicated (risk of bacteremia/sepsis). Treat with fluoroquinolones (4-6 weeks).'),

    -- PROSTATE CANCER (13-24)
    (v_topic_id, 'Prostate adenocarcinoma most commonly arises in which zone of the prostate?', '["Transitional (periurethral) zone", "Peripheral zone (posterior part of prostate — palpable on DRE as a hard nodule)", "Central zone", "Anterior fibromuscular stroma"]', 1, 'Prostate cancer originates in the peripheral zone (70% of cases), which is accessible on digital rectal examination (DRE) as a hard, irregular, non-tender nodule. BPH is in the transitional zone. Cancer in the peripheral zone does not cause obstructive symptoms early (unlike BPH) — it is often asymptomatic until advanced.'),
    (v_topic_id, 'The Gleason grading system scores prostate cancer from 2 to 10. What does the Gleason score represent?', '["PSA level times tumor volume", "Sum of the two most prevalent architectural patterns (grades 1-5) seen on biopsy — Grade 5 = most undifferentiated. Higher Gleason score = worse prognosis", "Number of positive biopsy cores", "Tumor stage (T1-T4)"]', 1, 'Gleason grading: pathologist assigns a grade (1-5) to the most common pattern PLUS the second most common pattern; sum = Gleason score. Low-grade: 6 (3+3) = well-differentiated, good prognosis. Intermediate: 7 (3+4 or 4+3). High-grade: 8-10 = poorly differentiated, high metastatic risk. Grade 4+3 is worse than 3+4 despite same sum.'),
    (v_topic_id, 'Prostate-Specific Antigen (PSA) is a serine protease produced by prostate epithelium. It is used as a tumor marker. What are the main causes of elevated PSA?', '["Prostate cancer only", "Prostate cancer, BPH, prostatitis (acute >> chronic), and post-instrumentation (DRE, TRUS, biopsy, cystoscopy)", "Bladder cancer and urethral stricture", "Testicular cancer"]', 1, 'PSA is organ-specific but NOT cancer-specific. Any process disrupting normal prostate architecture releases more PSA into blood. Acute prostatitis causes the highest acute PSA rise (can exceed 100). Ejaculation raises PSA mildly for 24-48 hours. For accurate PSA: avoid DRE, biopsy, or TRUS for 48 hours prior.'),
    (v_topic_id, 'High-grade Prostatic Intraepithelial Neoplasia (HGPIN) is the precursor lesion to prostate cancer. What are its histological features?', '["Invasive glands infiltrating perineurial spaces", "Architecturally benign glands with cytologically malignant cells (large nuclei, prominent nucleoli) — glands maintain basal cell layer (unlike invasive cancer which lacks basal cells)", "Small atrophic glands with no nucleoli", "Glands filled with mucin"]', 1, 'HGPIN: normal gland architecture (luminal pattern preserved) but cytological atypia (prominent nucleoli, nuclear enlargement) in the luminal cells. The basal cell layer is intact (p63 and high molecular weight cytokeratin positive). Invasive prostate cancer has NO basal cell layer — this is the key histological distinction.'),
    (v_topic_id, 'Prostate cancer classically metastasizes to bone. What is the characteristic type of bone metastasis?', '["Lytic (punched-out) lesions — as in multiple myeloma and renal cell carcinoma", "Osteoblastic (sclerotic) lesions — associated with elevated alkaline phosphatase and a positive bone scan", "Mixed lytic-sclerotic lesions only", "No bone involvement — prostate cancer only spreads to lymph nodes"]', 1, 'Prostate cancer causes OSTEOBLASTIC (sclerotic, blastic) bone metastases — abnormal new bone deposition around tumor cells. This contrasts with lytic lesions of myeloma and RCC. Alkaline phosphatase (ALP) is elevated (osteoblast marker). Bone scan: hot spots (increased uptake from osteoblast activity). Most common sites: lumbar vertebrae, pelvis, ribs.'),
    (v_topic_id, 'A patient with prostate cancer develops severe back pain and lower extremity weakness. What must be urgently excluded?', '["BPH causing urethral obstruction", "Epidural (spinal cord) compression from vertebral metastasis — requires urgent MRI spine and dexamethasone to prevent permanent paraplegia", "Psoas muscle spasm from radiation", "Peripheral neuropathy from chemotherapy"]', 1, 'Spinal cord compression is an oncologic emergency. Prostate cancer commonly metastasizes to lumbar and thoracic vertebrae. Tumor expansion into the epidural space compresses the cord. Presentation: back pain + progressive leg weakness/sensory loss + bowel/bladder dysfunction. Treatment: high-dose dexamethasone + urgent radiation or surgical decompression.'),
    (v_topic_id, 'Androgen Deprivation Therapy (ADT) is used for metastatic prostate cancer. What are the methods?', '["Chemotherapy with docetaxel alone", "Surgical castration (bilateral orchiectomy) OR medical castration with GnRH agonists (leuprolide, goserelin) — both lower testosterone to castrate levels (<50 ng/dL)", "Radiation to the prostate alone", "High-dose estrogen therapy only (historical)"]', 1, 'ADT eliminates testosterone (the primary driver of prostate cancer growth). GnRH agonists initially cause a testosterone flare (first 1-2 weeks) — prevent with anti-androgen (bicalutamide) during this period. Long-term ADT complications: hot flashes, osteoporosis, metabolic syndrome, anemia, sexual dysfunction, and increased cardiovascular risk.'),
    (v_topic_id, 'Castration-Resistant Prostate Cancer (CRPC) develops after ADT. What is the mechanism?', '["The cancer becomes estrogen-driven", "Cancer cells develop androgen receptor (AR) amplification/mutation, intratumoral androgen synthesis, or AR splice variants (e.g., AR-V7) that activate AR signaling despite low serum testosterone", "ADT causes immune tolerance to tumor cells", "Mutations in TP53 eliminate androgen dependence"]', 1, 'CRPC: PSA rises and/or clinical progression despite castrate testosterone levels. Mechanisms: AR amplification (more receptors needed per molecule), AR gain-of-function mutations (respond to non-androgen ligands), intratumoral steroidogenesis (tumor makes its own androgens), AR splice variants (AR-V7 lacks ligand-binding domain — constitutively active). Treated with enzalutamide, abiraterone, or docetaxel.'),
    (v_topic_id, 'Abiraterone acetate is used for CRPC. What is its mechanism?', '["It blocks the androgen receptor directly", "It inhibits CYP17A1 (17-alpha-hydroxylase/17,20-lyase), blocking androgen synthesis in the adrenal glands, testes, AND within the tumor itself", "It induces apoptosis via caspase activation", "It inhibits VEGF-driven angiogenesis"]', 1, 'CYP17A1 is required for androgen synthesis in adrenal cortex, testes, and tumor cells. Abiraterone blocks this enzyme, profoundly suppressing androgens even below castrate levels. Must be given with prednisone (to prevent mineralocorticoid excess from upstream steroid accumulation causing hypertension and hypokalemia).'),
    (v_topic_id, 'BRCA2 mutations increase the risk of prostate cancer significantly. What targeted therapy is approved for BRCA-mutated CRPC?', '["Imatinib (BCR-ABL inhibitor)", "PARP inhibitors (olaparib, rucaparib) — BRCA-mutated tumors rely on PARP for DNA repair; PARP inhibition causes synthetic lethality in BRCA-deficient tumor cells", "Checkpoint inhibitors (pembrolizumab) for all CRPC", "Anti-HER2 antibody (trastuzumab)"]', 1, 'BRCA1/2 and other HRR (homologous recombination repair) gene mutations are found in ~25% of metastatic CRPC. These tumors cannot repair double-strand DNA breaks. PARP inhibitors block the alternative repair pathway, causing lethal DNA damage in HRR-deficient tumor cells only (synthetic lethality concept).'),
    (v_topic_id, 'Prostatic acid phosphatase (PAP) was historically used as a prostate cancer marker. It has been largely replaced by PSA. Why is PAP less useful?', '["PAP is more sensitive than PSA", "PAP is less sensitive and less specific than PSA; elevated only in advanced (metastatic) disease, not in localized prostate cancer", "PAP can only detect BPH", "PAP requires tissue biopsy to measure"]', 1, 'PAP (acid phosphatase from prostate epithelium) was the first prostate tumor marker. It is elevated in metastatic prostate cancer but normal in localized disease — making it useless for early detection. PSA, by contrast, is elevated even in localized cancer. PAP is now used mainly in forensic serology to detect seminal fluid in sexual assault cases.'),

    -- PROSTATITIS (25-30)
    (v_topic_id, 'Chronic bacterial prostatitis presents how?', '["Fever and acute systemic illness", "Recurrent urinary tract infections (same organism), perineal discomfort, variable LUTS, mildly tender or non-tender prostate on DRE — same organism cultured from expressed prostatic secretions", "Acute onset perineal pain and high fever", "Asymptomatic bacteriuria only"]', 1, 'Chronic bacterial prostatitis: the prostate serves as a bacterial reservoir causing recurrent UTIs with the same pathogen (E. coli most common). Symptoms are milder than acute prostatitis. Diagnosis: Meares-Stamey 4-glass test or simpler 2-glass (VB2 vs. EPS/VB3). Treatment: fluoroquinolones for 4-6 weeks (excellent prostatic penetration).'),
    (v_topic_id, 'Chronic Pelvic Pain Syndrome (CPPS, previously Chronic Prostatitis Type III) is the most common prostatitis syndrome. What characterizes it?', '["A specific identifiable bacterial pathogen in prostatic secretions", "Pelvic/perineal pain lasting >3 months with NO identifiable bacterial cause — most common prostatitis syndrome (90% of all prostatitis cases); pathogenesis unclear (possibly neuromuscular, psychological)", "Elevated PSA >100 without symptoms", "Acute fever and tender prostate"]', 1, 'CPPS (NIH Category III): most common form of prostatitis (~90% of cases). Pelvic pain >3 months. Bacteria negative on all cultures. Subdivided into IIIa (inflammatory - WBCs in EPS) and IIIb (non-inflammatory). Pathogenesis: pelvic floor muscle dysfunction, neurogenic inflammation, or psychological factors. Treatment: multimodal (alpha-blockers, NSAIDS, pelvic PT, behavioral).'),
    (v_topic_id, 'Granulomatous prostatitis can mimic prostate cancer on DRE and PSA. What is the most common cause in the United States?', '["Sarcoidosis", "Post-TURP/biopsy granulomas or BCG instillation for bladder cancer therapy — BCG (Bacillus Calmette-Guerin) causes granulomatous inflammation in the prostate", "Tuberculosis (in immunocompetent patients)", "Coccidioidomycosis"]', 1, 'BCG immunotherapy for bladder cancer is the most common cause of granulomatous prostatitis in the US. BCG is instilled into the bladder and can reflux into prostatic ducts, causing granulomatous reaction. May cause massively elevated PSA and hard prostate mimicking cancer. History of BCG therapy is the key clue.'),
    (v_topic_id, 'Xanthogranulomatous prostatitis is characterized by which cell type on histology?', '["Epithelioid granulomas with Langhans giant cells (TB pattern)", "Lipid-laden foamy macrophages (xanthoma cells) admixed with lymphocytes and plasma cells", "Eosinophils predominantly (allergic prostatitis)", "Plasma cells with Russell bodies"]', 1, 'Xanthogranulomatous prostatitis: sheets of foamy lipid-laden macrophages (xanthoma cells) in the prostate. It can mimic prostate cancer on imaging and clinically. Similar to xanthogranulomatous processes in other organs (kidney, gallbladder). Must be distinguished from clear cell carcinoma and foamy gland carcinoma on biopsy.'),
    (v_topic_id, 'A young man presents with acute urinary retention, fever, and an extremely tender prostate. PSA is markedly elevated. What should NOT be done initially?', '["Urethral catheterization for decompression", "Vigorous prostate massage (to express prostatic secretions for culture) — risks seeding bacteria into the bloodstream causing septicemia", "Blood cultures", "Starting IV fluoroquinolone antibiotics"]', 1, 'In acute bacterial prostatitis, prostate massage is contraindicated due to risk of bacteremia and septic shock. The prostate is exquisitely tender and hyperemic with engorged venous sinuses. Bacteria can be easily disseminated with massage. Diagnosis is clinical + urine culture. Treatment: IV antibiotics (fluoroquinolone or 3rd gen cephalosporin + aminoglycoside for severe cases).'),

    -- PENILE PATHOLOGY (31-38)
    (v_topic_id, 'Phimosis is defined as?', '["Inability to retract the foreskin over the glans penis", "Inability to return the retracted foreskin back over the glans (paraphimosis) — this is a urological emergency", "Painful erection without ejaculation", "Penile curvature during erection"]', 0, 'Phimosis: foreskin too tight to retract over glans. Can be physiological in infants (normal until age 3-4) or pathological (recurrent balanitis, BXO/lichen sclerosus). Complications: difficulty urinating, balanitis, paraphimosis. Treatment: topical steroids, preputioplasty, or circumcision.'),
    (v_topic_id, 'Paraphimosis is a urological emergency. What makes it an emergency?', '["Infection risk from retained smegma", "The retracted foreskin forms a constricting ring behind the glans, causing venous congestion and lymphedema of the glans, which can progress to arterial occlusion and ischemic necrosis", "Pain alone", "Risk of penile fracture"]', 1, 'Paraphimosis: foreskin retracted and cannot return over the glans. The tight ring of foreskin constricts venous/lymphatic drainage → edematous, engorged glans. If not reduced promptly, arterial supply is cut off → glans necrosis. Reduction maneuvers: manual compression + reduction, or emergency dorsal slit if manual fails.'),
    (v_topic_id, 'Peyronie Disease is characterized by penile curvature during erection. What is the underlying pathology?', '["Venous thrombosis of the corpus spongiosum", "Focal fibrosis (fibrous plaque) within the tunica albuginea of the corpora cavernosa, causing inelastic scar tissue that prevents normal expansion during erection, creating curvature toward the plaque", "Smooth muscle atrophy of the corpus cavernosum", "Calcification of the urethra"]', 1, 'Peyronie disease: abnormal fibroproliferative healing response (possibly from repeated microtrauma during intercourse) within the tunica albuginea creates a fibrous plaque. The plaque does not expand with erection, tethering that side and causing angular deformity. Associations: Dupuytren contracture (same fibroproliferative diathesis). Treatment: collagenase (Xiaflex), surgery.'),
    (v_topic_id, 'Priapism is a prolonged painful erection lasting >4 hours not related to sexual stimulation. Which type of priapism is a urological emergency requiring immediate intervention?', '["High-flow (non-ischemic) priapism from arteriovenous fistula", "Low-flow (ischemic/venoocclusive) priapism from venous outflow obstruction causing hypoxic, acidotic blood in the corpora — requires immediate aspiration and intracavernosal sympathomimetics to prevent fibrosis/impotence", "Both types are equally urgent", "Neither type is an emergency"]', 1, 'Low-flow (ischemic) priapism: venous outflow obstructed (sickle cell disease, leukemia, hypercoagulability, intracavernosal drug injection). Trapped blood becomes hypoxic and acidotic → progressive cavernosal smooth muscle necrosis → fibrosis → permanent erectile dysfunction. Treatment: aspiration + phenylephrine (alpha-agonist causes detumescence). Must treat within 4-6 hours to preserve erectile function.'),
    (v_topic_id, 'Balanitis Xerotica Obliterans (BXO) is the penile equivalent of which dermatological condition?', '["Lichen planus", "Lichen sclerosus (chronic sclerosing inflammatory condition affecting the glans and prepuce — causes white plaques, phimosis, urethral stenosis, and is associated with increased risk of penile squamous cell carcinoma)", "Psoriasis", "Eczema"]', 1, 'BXO = penile lichen sclerosus. Clinically: white atrophic plaques on the glans and prepuce causing severe phimosis, dyspareunia, and urethral meatal stenosis. Histology: epidermal atrophy, hyalinized collagen in dermis, band-like lymphocytic infiltrate. Risk of SCC (~4-6% lifetime risk) — requires surveillance.'),
    (v_topic_id, 'Condyloma Acuminata (genital warts) on the penis are caused by which HPV types?', '["HPV 16 and 18 (high-risk, oncogenic)", "HPV 6 and 11 (low-risk, non-oncogenic) — cause benign exophytic warts (condylomata acuminata) but rarely progress to malignancy", "HPV 31 and 33", "HPV 45 and 56"]', 1, 'HPV 6 and 11 cause 90% of genital warts (condylomata acuminata) — soft, flesh-colored, cauliflower-like exophytic lesions. These are low-risk strains that rarely cause cancer. HPV 16/18/31/33 are high-risk oncogenic strains causing CIN, cervical, penile, anal, oropharyngeal cancers. Gardasil-9 covers both low-risk (6,11) and high-risk (16,18,31,33,45,52,58) strains.'),
    (v_topic_id, 'Squamous Cell Carcinoma of the penis is most strongly associated with which risk factors?', '["BPH and prostatitis", "HPV infection (types 16/18), lack of circumcision, phimosis (smegma retention), and smoking", "Anabolic steroid use", "Diabetes mellitus"]', 1, 'Penile SCC risk factors: HPV 16/18 (associated with basaloid/warty subtypes); uncircumcised men (phimosis traps smegma, creating chronic irritation); lichen sclerosus (BXO); smoking. Circumcision at birth nearly eliminates risk. Presents as a painless indurated ulcer or plaque on the glans or prepuce. HPV-associated penile SCC has better prognosis than HPV-negative keratinizing SCC.'),
    (v_topic_id, 'Bowen Disease of the penis (penile intraepithelial neoplasia, high-grade) presents as?', '["Soft papillary wart-like growth (condyloma)", "A solitary, well-demarcated, erythematous plaque on the shaft (Bowen disease) or glans/prepuce (erythroplasia of Queyrat) — both are SCC in situ with high malignant potential", "Painless ulcer with rolled edges on the frenulum", "Subcutaneous nodule without skin changes"]', 1, 'Penile SCC in situ has two clinical presentations: (1) Bowen disease: on the shaft — leukoplakic or erythematous plaque; (2) Erythroplasia of Queyrat: on the glans/prepuce — velvety red plaque with higher (~30%) risk of invasive transformation than Bowen disease. Both show full-thickness epithelial dysplasia on histology.')

    ON CONFLICT DO NOTHING;

END $$;

COMMIT;
